cat > /workspace/dev/dump.rs <<'EOF'
use std::io::Write;
use rust_unit_merge::topology::*;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = args[1].as_str();
    let nums: Vec<usize> = args[2..].iter().filter_map(|s| s.parse().ok()).collect();
    let strs: Vec<String> = args[2..].iter().filter(|s| s.parse::<usize>().is_err()).cloned().collect();
    let case = match mode {
        "clos" => build_clos(nums[0], 1, None, None, nums[1] != 0,
                            if strs[0] == "pod" { ClosSourceGroupScope::Pod } else { ClosSourceGroupScope::Tor }),
        "leaf-spine" => build_leaf_spine(nums[0], nums[1], 1),
        "torus2d" => build_torus2d(nums[0], 1, if strs[0] == "row" { Torus2DSourceGroupScope::Row } else { Torus2DSourceGroupScope::Host }),
        "torus3d" => build_torus3d(nums[0], 1, if strs[0] == "line" { Torus3DSourceGroupScope::Line } else { Torus3DSourceGroupScope::Host }),
        "dragonfly" => build_dragonfly(nums[0], nums[1], nums[2], Some(1), 1.0, 1, 0,
                            match strs[0].as_str() { "router" => DragonflySourceGroupScope::Router, "group" => DragonflySourceGroupScope::Group, _ => DragonflySourceGroupScope::SourceTargetGroup }),
        "dragonfly-plus" => build_dragonfly_plus(nums[0], nums[1], nums[2], nums[3], nums[4] != 0, 1, 0,
                            if strs[0] == "group" { DragonflyPlusSourceGroupScope::Group } else { DragonflyPlusSourceGroupScope::Tor }),
        _ => panic!("mode"),
    };
    let p = &case.problem;
    let n = p.num_nodes;
    // domain ids
    let domain: Vec<usize> = match p.demand_merge_classes.as_ref() {
        Some(c) => c.clone(),
        None => {
            let mut owner = vec![usize::MAX; n];
            for (id, mem) in p.source_merge_groups.iter().enumerate() { for &x in mem { owner[x] = id; } }
            p.demands.iter().map(|d| owner[d.src]).collect()
        }
    };
    let mut out = String::new();
    out.push_str(&format!("{}\n", n));
    for (i, d) in p.demands.iter().enumerate() {
        out.push_str(&format!("{} {} {} {}\n", d.src, d.dst, domain[i],
            d.footprint.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")));
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes()).unwrap();
}
EOF
cd /workspace/dev && export LD_LIBRARY_PATH=/opt/rust/lib && /opt/rust/bin/rustc --edition 2021 --target x86_64-unknown-linux-musl -C opt-level=2 -A warnings --extern rust_unit_merge=/workspace/tmp/unit-merge-build/librust_unit_merge.rlib -C linker=/opt/rust/lib/rustlib/x86_64-unknown-linux-gnu/bin/rust-lld dump.rs -o dump 2>&1 | head -20 && echo BUILD_OK && ./dump leaf-spine 3 2 | head -4
